const DEFAULT_PORT = 28710;

// Automatically sync configuration from config.json (generated by desktop app)
async function syncWithConfigFile(force = false) {
  try {
    const resp = await fetch(chrome.runtime.getURL("config.json"));
    if (!resp.ok) return null;
    const fileCfg = await resp.json();
    const current = await chrome.storage.local.get(["bridgePort", "bridgeToken"]);

    let updated = false;
    const toSet = {};

    if (fileCfg.bridge_port && fileCfg.bridge_port !== current.bridgePort) {
      toSet.bridgePort = fileCfg.bridge_port;
      updated = true;
    }
    if (fileCfg.bridge_token && fileCfg.bridge_token !== current.bridgeToken) {
      toSet.bridgeToken = fileCfg.bridge_token;
      updated = true;
    }

    if (updated || force) {
      await chrome.storage.local.set(toSet);
      console.log("[RipSync] Bridge ayarları config.json ile eşitlendi:", toSet);
    }
    return fileCfg;
  } catch (e) {
    return null;
  }
}

// Resolve bridge configuration (port & authentication token)
async function getBridgeConfig() {
  let { bridgePort, bridgeToken, shareCookies, allowedCookieDomains } = await chrome.storage.local.get([
    "bridgePort",
    "bridgeToken",
    "shareCookies",
    "allowedCookieDomains"
  ]);

  // If token or port is missing, auto-discover from extension config.json
  if (!bridgeToken || !bridgePort) {
    const fileCfg = await syncWithConfigFile(true);
    if (fileCfg) {
      bridgeToken = fileCfg.bridge_token || bridgeToken;
      bridgePort = fileCfg.bridge_port || bridgePort;
    }
  }

  const port = bridgePort || DEFAULT_PORT;
  return {
    apiBase: `http://127.0.0.1:${port}`,
    apiToken: bridgeToken || "",
    bridgePort: port,
    bridgeToken: bridgeToken || "",
    shareCookies: !!shareCookies,
    allowedCookieDomains: Array.isArray(allowedCookieDomains) ? allowedCookieDomains : []
  };
}

// Safely obtain cookies strictly when authorized by user consent
async function getSafeCookiesForUrl(targetUrl) {
  if (!targetUrl || (!targetUrl.startsWith("http://") && !targetUrl.startsWith("https://"))) {
    return "";
  }

  const cfg = await getBridgeConfig();
  // Privacy & Security: Do not harvest or transmit cookies unless explicitly enabled by user
  if (!cfg.shareCookies) {
    return "";
  }

  // If a domain whitelist is configured, enforce that target domain is included
  try {
    const urlObj = new URL(targetUrl);
    const host = urlObj.hostname.toLowerCase();
    if (cfg.allowedCookieDomains.length > 0) {
      const isAllowed = cfg.allowedCookieDomains.some(d => host === d.toLowerCase() || host.endsWith("." + d.toLowerCase()));
      if (!isAllowed) {
        return "";
      }
    }

    const cookies = await chrome.cookies.getAll({ url: targetUrl });
    return (cookies || []).map(c => `${c.name}=${c.value}`).join("; ");
  } catch (err) {
    console.warn("[RipSync] Çerezler alınamadı:", err);
    return "";
  }
}

// Check desktop bridge status and authentication with auto-discovery on failure
async function checkDesktopApp() {
  let cfg = await getBridgeConfig();
  try {
    const headers = {};
    if (cfg.apiToken) {
      headers["X-RipSync-Token"] = cfg.apiToken;
    }
    const res = await fetch(`${cfg.apiBase}/api/status`, {
      method: "GET",
      headers: headers
    });
    if (res.ok) {
      let data = {};
      try { data = await res.json(); } catch(e) {}
      if (data && data.power_alert) {
        handlePowerAlert(data.power_alert);
      } else {
        handlePowerAlert(null);
      }
      return {
        ok: true,
        status: res.status,
        authenticated: true,
        powerAlert: data.power_alert || null
      };
    }
    if (res.status === 401) {
      await syncWithConfigFile(true);
      return { ok: false, status: 401, authenticated: false, error: "unauthorized" };
    }
    return {
      ok: false,
      status: res.status,
      authenticated: false
    };
  } catch (err) {
    // Port might have changed due to port conflict or user settings!
    const synced = await syncWithConfigFile(false);
    if (synced && synced.bridge_port && `http://127.0.0.1:${synced.bridge_port}` !== cfg.apiBase) {
      try {
        const retryHeaders = {};
        if (synced.bridge_token) {
          retryHeaders["X-RipSync-Token"] = synced.bridge_token;
        }
        const retryRes = await fetch(`http://127.0.0.1:${synced.bridge_port}/api/status`, {
          method: "GET",
          headers: retryHeaders
        });
        if (retryRes.ok) {
          let retryData = {};
          try { retryData = await retryRes.json(); } catch(e) {}
          if (retryData && retryData.power_alert) {
            handlePowerAlert(retryData.power_alert);
          }
          return {
            ok: true,
            status: retryRes.status,
            authenticated: true,
            powerAlert: retryData.power_alert || null
          };
        }
      } catch (retryErr) {
        // Still unreachable
      }
    }
    handlePowerAlert(null);
    return {
      ok: false,
      status: 0,
      authenticated: false,
      error: "offline"
    };
  }
}

// Forward download request to desktop app with authorization header and fallback retry
async function sendDownloadToApp(data) {
  let cfg = await getBridgeConfig();
  try {
    const headers = {
      "Content-Type": "application/json"
    };
    if (cfg.apiToken) {
      headers["X-RipSync-Token"] = cfg.apiToken;
    }
    const res = await fetch(`${cfg.apiBase}/api/download`, {
      method: "POST",
      headers: headers,
      body: JSON.stringify(data)
    });
    return res.ok;
  } catch (err) {
    // Connection failed: check if port changed
    const synced = await syncWithConfigFile(false);
    if (synced && synced.bridge_port && `http://127.0.0.1:${synced.bridge_port}` !== cfg.apiBase) {
      try {
        const retryHeaders = { "Content-Type": "application/json" };
        if (synced.bridge_token) {
          retryHeaders["X-RipSync-Token"] = synced.bridge_token;
        }
        const retryRes = await fetch(`http://127.0.0.1:${synced.bridge_port}/api/download`, {
          method: "POST",
          headers: retryHeaders,
          body: JSON.stringify(data)
        });
        return retryRes.ok;
      } catch (retryErr) {}
    }
    console.error("[RipSync] Masaüstü uygulamasına bağlanılamadı:", err);
    return false;
  }
}

// Default settings on install/update
chrome.runtime.onInstalled.addListener(async () => {
  const existing = await chrome.storage.local.get(["interceptDownloads", "showVideoSniffer", "shareCookies"]);
  await chrome.storage.local.set({
    interceptDownloads: existing.interceptDownloads !== undefined ? existing.interceptDownloads : true,
    showVideoSniffer: existing.showVideoSniffer !== undefined ? existing.showVideoSniffer : true,
    shareCookies: existing.shareCookies !== undefined ? existing.shareCookies : false, // Default OFF for safety
    allowedCookieDomains: existing.allowedCookieDomains || []
  });

  // Attempt auto-reading config.json
  await getBridgeConfig();

  // Context Menu setup
  chrome.contextMenus.removeAll(() => {
    chrome.contextMenus.create({
      id: "ripsync-download-link",
      title: "Bu bağlantıyı RipSync ile indir",
      contexts: ["link", "video", "audio", "image"]
    });
  });
});

// Intercept browser downloads
chrome.downloads.onCreated.addListener(async (downloadItem) => {
  const { interceptDownloads } = await chrome.storage.local.get("interceptDownloads");
  if (!interceptDownloads) return;

  // Avoid intercepting non-http URLs
  if (!downloadItem.url.startsWith("http://") && !downloadItem.url.startsWith("https://")) {
    return;
  }

  // Verify desktop bridge is active and authenticated before cancelling browser download
  const status = await checkDesktopApp();
  if (!status.ok) return;

  // Cancel the native Chrome download
  chrome.downloads.cancel(downloadItem.id, () => {
    chrome.downloads.erase({ id: downloadItem.id });
  });

  // Safe cookie resolution (only sent if user enabled cookie sharing)
  const cookieHeader = await getSafeCookiesForUrl(downloadItem.url);

  await sendDownloadToApp({
    url: downloadItem.url,
    filename: downloadItem.filename ? downloadItem.filename.replace(/^.*[\\\/]/, '') : "",
    referer: downloadItem.referrer || "",
    cookies: cookieHeader,
    userAgent: navigator.userAgent,
    mimeType: downloadItem.mime || ""
  });
});

// Handle Context Menu clicks
chrome.contextMenus.onClicked.addListener(async (info, tab) => {
  if (info.menuItemId === "ripsync-download-link") {
    const targetUrl = info.linkUrl || info.srcUrl || info.pageUrl;
    if (!targetUrl) return;

    const cookieHeader = await getSafeCookiesForUrl(targetUrl);

    await sendDownloadToApp({
      url: targetUrl,
      filename: "",
      referer: tab ? tab.url : "",
      cookies: cookieHeader,
      userAgent: navigator.userAgent
    });
  }
});

// Handle messages from content script or popup
chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
  if (request.action === "download_media") {
    (async () => {
      const cookieHeader = await getSafeCookiesForUrl(request.url);

      const success = await sendDownloadToApp({
        url: request.url,
        filename: request.filename || "",
        quality: request.quality || "max",
        referer: sender.tab ? sender.tab.url : "",
        cookies: cookieHeader,
        userAgent: navigator.userAgent
      });
      sendResponse({ success });
    })();
    return true; // Keep async response channel open
  }

  if (request.action === "check_status") {
    checkDesktopApp().then(res => sendResponse(res));
    return true;
  }

  if (request.action === "sync_config") {
    (async () => {
      try {
        const resp = await fetch(chrome.runtime.getURL("config.json"));
        if (resp.ok) {
          const cfg = await resp.json();
          await chrome.storage.local.set({
            bridgeToken: cfg.bridge_token || "",
            bridgePort: cfg.bridge_port || DEFAULT_PORT
          });
          const st = await checkDesktopApp();
          sendResponse({ success: true, status: st });
          return;
        }
      } catch (e) {}
      sendResponse({ success: false });
    })();
    return true;
  }

  if (request.action === "get_bridge_config") {
    (async () => {
      try {
        const cfg = await getBridgeConfig();
        sendResponse({ success: true, bridgePort: cfg.bridgePort, bridgeToken: cfg.bridgeToken });
      } catch (e) {
        sendResponse({ success: false });
      }
    })();
    return true;
  }

  if (request.action === "power_control") {
    sendPowerControl(request.command, request.seconds).then(ok => sendResponse({ success: ok }));
    return true;
  }
});

// Power Management Alert & Browser Notification Handling
let lastPowerAlertState = null;

async function sendPowerControl(command, seconds = 300) {
  const cfg = await getBridgeConfig();
  try {
    const headers = {
      "Content-Type": "application/json"
    };
    if (cfg.apiToken) {
      headers["X-RipSync-Token"] = cfg.apiToken;
    }
    const resp = await fetch(`${cfg.apiBase}/api/power_control`, {
      method: "POST",
      headers: headers,
      body: JSON.stringify({ command, seconds })
    });
    return resp.ok;
  } catch (err) {
    console.error("[RipSync] Güç komutu gönderilemedi:", err);
    return false;
  }
}

function handlePowerAlert(alert) {
  if (!chrome.notifications) return;

  if (!alert || !alert.is_active) {
    if (lastPowerAlertState && lastPowerAlertState.is_active) {
      chrome.notifications.clear("ripsync_power_alert", () => {});
    }
    lastPowerAlertState = alert;
    return;
  }

  // If power countdown is suspended
  if (alert.is_suspended) {
    chrome.notifications.clear("ripsync_power_alert", () => {});
    if (!lastPowerAlertState || !lastPowerAlertState.is_suspended) {
      chrome.notifications.create("ripsync_power_suspended", {
        type: "basic",
        iconUrl: "icons/icon128.png",
        title: "⚠️ RipSync: Kapatma İşlemi Askıya Alındı",
        message: alert.suspend_reason || "Aktif kullanım algılandığı için kapatma işlemi durduruldu.",
        priority: 2
      }, () => {});
    }
    lastPowerAlertState = alert;
    return;
  }

  // Active power countdown
  const actionName = alert.action === "shutdown" ? "Kapatılıyor" : "Uyku Moduna Alınıyor";
  const iconEmoji = alert.action === "shutdown" ? "🛑" : "🌙";
  const remaining = alert.remaining_seconds !== undefined ? alert.remaining_seconds : 30;

  chrome.notifications.create("ripsync_power_alert", {
    type: "basic",
    iconUrl: "icons/icon128.png",
    title: `${iconEmoji} RipSync: Bilgisayar ${actionName} (${remaining} sn)`,
    message: `Kuyruktaki tüm indirmeler tamamlandı. Sistem ${remaining} saniye içinde ${actionName.toLowerCase()}. Kaydedilmemiş işlerinizi korumak için işlemi iptal edin veya askıya alın.`,
    buttons: [
      { title: "🛑 İptal Et" },
      { title: "⏸️ Askıya Al / Ertele" }
    ],
    requireInteraction: true,
    priority: 2
  }, () => {});

  lastPowerAlertState = alert;
}

if (chrome.notifications && chrome.notifications.onButtonClicked) {
  chrome.notifications.onButtonClicked.addListener((notifId, btnIdx) => {
    if (notifId === "ripsync_power_alert") {
      if (btnIdx === 0) {
        sendPowerControl("cancel");
        chrome.notifications.clear(notifId, () => {});
      } else if (btnIdx === 1) {
        sendPowerControl("suspend");
        chrome.notifications.clear(notifId, () => {});
      }
    }
  });

  chrome.notifications.onClicked.addListener((notifId) => {
    if (notifId === "ripsync_power_alert") {
      sendPowerControl("suspend");
      chrome.notifications.clear(notifId, () => {});
    }
  });
}

// Periodic background check to catch power alerts while user is browsing
setInterval(() => {
  checkDesktopApp().catch(() => {});
}, 3000);

